// This file is generated by AI.

// 「点诊断跳转」这条链路的载荷。
//
// 诊断列表只按**起点**调 `requestReveal`, 而编辑器要能选中整段就必须在载荷里拿到**结束位置**;
// 拿不到时退回"只放光标"。
import { beforeEach, describe, expect, it } from 'vitest';

import type { LspDiagnostic } from '../src/state/store.svelte';
import { actions, appStore, useAppStore } from '../src/state/store.svelte';

const SCENE = 'C:\\Game\\game\\scene\\start.txt';

/** LSP 的 range 是 **0 起算**, 而诊断列表给的是 1 起算 —— 这里故意错开一位来盯住换算。 */
function diag(startLine: number, startChar: number, endLine: number, endChar: number): LspDiagnostic {
  return {
    range: { start: { line: startLine, character: startChar }, end: { line: endLine, character: endChar } },
    severity: 1,
    code: 'WG007',
    message: '测试诊断',
  };
}

describe('requestReveal 带上诊断的结束位置', () => {
  beforeEach(() => {
    actions.setDiagnostics(SCENE, [diag(11, 15, 11, 27)]);
    actions.clearReveal();
  });

  it('起点能对上时, 载荷里带上 1 起算的结束行列', () => {
    actions.requestReveal(SCENE, 12, 16);
    expect(appStore.revealRequest).toMatchObject({ path: SCENE, line: 12, column: 16, endLine: 12, endColumn: 28 });
  });

  it('起点对不上时不带结束位置 (编辑器退回"只放光标")', () => {
    actions.requestReveal(SCENE, 12, 17);
    expect(appStore.revealRequest?.endLine).toBeUndefined();
    expect(appStore.revealRequest?.endColumn).toBeUndefined();
  });

  it('文件没有诊断时同样不带结束位置', () => {
    actions.requestReveal('C:\\Game\\game\\scene\\other.txt', 3, 1);
    expect(appStore.revealRequest?.endLine).toBeUndefined();
  });

  it('每次请求都换新 token, 且不会把上一次的结束位置带过来', () => {
    actions.requestReveal(SCENE, 12, 16);
    const first = appStore.revealRequest;
    actions.requestReveal(SCENE, 99, 1);
    const second = appStore.revealRequest;
    expect(second?.token).toBe((first?.token ?? 0) + 1);
    expect(second?.endLine).toBeUndefined();
  });

  it('消费之后请求被清空 (一次性动作, 切回来不会又跳一次)', () => {
    actions.requestReveal(SCENE, 12, 16);
    actions.clearReveal();
    expect(useAppStore.getState().revealRequest).toBeNull();
  });

  /*
   * 诊断列表手上**本来就有**结束位置 (`DiagnosticEntry.endLine/endColumn`), 应当由调用方直接传入,
   * 而不是让 store 去字典里反查 —— 反查依赖 key 与行列口径一致, 任何一处漂移都会静默退化成
   * "只放光标"。下面两条钉住这条"以调用方为准"的路径。
   */
  it('调用方直接给结束位置时以它为准 (不查 store)', () => {
    actions.requestReveal(SCENE, 12, 16, { line: 12, column: 20 });
    expect(appStore.revealRequest).toMatchObject({ line: 12, column: 16, endLine: 12, endColumn: 20 });
  });

  it('即使 store 里没有对应的诊断, 调用方给的结束位置也照样生效', () => {
    actions.setDiagnostics(SCENE, []);
    actions.requestReveal(SCENE, 5, 1, { line: 5, column: 9 });
    expect(appStore.revealRequest).toMatchObject({ endLine: 5, endColumn: 9 });
  });
});
